breach.segment:
// mysql/max_connections is emitted only by MySQL, so this also scopes the rule to MySQL.
// At least 3 observed minutes, so one late sample does not decide.
WHERE max_connections > 0 AND observed_minutes >= 3
// Threshold: every observed minute at or above 90% of max_connections; at 100% new connections are refused
| WHERE lowest_usage >= 0.9
| EVAL connection_usage_pct = ROUND(TO_DOUBLE(connections) * 100.0 / max_connections, 1),
       lowest_usage_pct = ROUND(lowest_usage * 100, 1)
| SORT connection_usage_pct DESC, database_id ASC
| LIMIT 100
| KEEP database_id, connection_usage_pct, connections, max_connections, lowest_usage_pct, observed_minutes
